import java.util.*;
import java.util.concurrent.*;
import java.util.function.*;

public class Cow {
    static void t(String n, Supplier<Object> s) {
        try { System.out.println(n + " = " + s.get()); }
        catch (Throwable e) { System.out.println(n + " ! " + e.getClass().getName() + (e.getMessage() == null ? "" : ": " + e.getMessage())); }
    }
    static CopyOnWriteArrayList<Integer> fresh() { return new CopyOnWriteArrayList<>(List.of(0, 1, 2, 3, 4, 5)); }
    static void after(String n, Consumer<CopyOnWriteArrayList<Integer>> op) {
        t("after " + n + " get", () -> { var l = fresh(); var s = l.subList(1, 4); op.accept(l); return s.get(0); });
        t("after " + n + " size", () -> { var l = fresh(); var s = l.subList(1, 4); op.accept(l); return s.size(); });
    }
    public static void main(String[] a) {
        after("add", l -> l.add(9));
        after("add(i)", l -> l.add(1, 9));
        after("addAll", l -> l.addAll(List.of(7)));
        after("addAll empty", l -> l.addAll(List.of()));
        after("addAll(i) empty", l -> l.addAll(1, List.of()));
        after("addIfAbsent present", l -> l.addIfAbsent(3));
        after("addIfAbsent new", l -> l.addIfAbsent(30));
        after("addAllAbsent none", l -> l.addAllAbsent(List.of(1)));
        after("set diff", l -> l.set(1, 9));
        after("set same", l -> l.set(1, 1));
        after("remove(i)", l -> l.remove(0));
        after("remove(o) missing", l -> l.remove((Object) 99));
        after("remove(o)", l -> l.remove((Object) 5));
        after("removeIf none", l -> l.removeIf(x -> false));
        after("removeIf some", l -> l.removeIf(x -> x == 5));
        after("removeAll none", l -> l.removeAll(List.of(99)));
        after("removeAll some", l -> l.removeAll(List.of(5)));
        after("retainAll all", l -> l.retainAll(List.of(0, 1, 2, 3, 4, 5)));
        after("retainAll some", l -> l.retainAll(List.of(1)));
        after("replaceAll", l -> l.replaceAll(x -> x));
        after("sort", l -> l.sort(null));
        after("clear", l -> l.clear());
        after("clear empty", l -> { l.clear(); });
        after("forEach", l -> l.forEach(x -> {}));
        after("reversed add", l -> l.reversed().add(1));
        t("clear twice", () -> { var l = new CopyOnWriteArrayList<Integer>(); var s = l.subList(0, 0); l.clear(); return s.size(); });
        t("empty sub after add", () -> { var l = new CopyOnWriteArrayList<Integer>(); var s = l.subList(0, 0); l.add(1); return s.size(); });
        t("loop add", () -> { var s = fresh().subList(1, 3); int n = 0; for (Integer x : s) { s.add(0, x); if (++n > 50) return "runaway"; } return n; });
        t("loop add end", () -> { var l = fresh(); var s = l.subList(1, 3); int n = 0; for (Integer x : s) { s.add(x); if (++n > 50) return "runaway"; } return n + " " + l + " " + s; });
        t("loop remove", () -> { var l = fresh(); var s = l.subList(1, 5); int n = 0; for (Integer x : s) { s.remove(0); n++; } return n + " " + l + " " + s; });
        t("iter, list add, hasNext", () -> { var l = fresh(); var s = l.subList(1, 3); var i = s.iterator(); l.add(9); return i.hasNext() + " " + i.next(); });
        t("iter, list add, creation", () -> { var l = fresh(); var s = l.subList(1, 3); l.add(9); return s.iterator(); });
        t("iter, part add, next", () -> { var l = fresh(); var s = l.subList(1, 3); var i = s.iterator(); s.add(9); return i.next() + " " + i.next() + " " + i.hasNext(); });
        t("iter remove", () -> { var l = fresh(); var s = l.subList(1, 3); var i = s.iterator(); i.next(); i.remove(); return 1; });
        t("listIterator set", () -> { var l = fresh(); var s = l.subList(1, 3); var i = s.listIterator(); i.next(); i.set(1); return 1; });
        t("listIterator add", () -> { var l = fresh(); var s = l.subList(1, 3); var i = s.listIterator(); i.add(1); return 1; });
        t("listIterator(2)", () -> { var l = fresh(); var s = l.subList(1, 3); var i = s.listIterator(2); return i.hasNext() + " " + i.previous() + " " + i.nextIndex() + " " + i.previousIndex(); });
        t("listIterator(3)", () -> { var l = fresh(); var s = l.subList(1, 3); return s.listIterator(3); });
        t("listIterator(-1)", () -> { var l = fresh(); var s = l.subList(1, 3); return s.listIterator(-1); });
        t("listIterator stale", () -> { var l = fresh(); var s = l.subList(1, 3); l.add(1); return s.listIterator(9); });
        t("iter walk back", () -> { var l = fresh(); var s = l.subList(1, 4); var i = s.listIterator(3); return i.previous() + " " + i.previous() + " " + i.previous() + " " + i.hasPrevious() + " " + i.nextIndex(); });
        t("iter next past end", () -> { var s = fresh().subList(1, 2); var i = s.iterator(); i.next(); return i.next(); });
        t("iter previous at start", () -> { var s = fresh().subList(1, 2); var i = s.listIterator(); return i.previous(); });
        t("iter forEachRemaining", () -> { var s = fresh().subList(1, 4); var i = s.iterator(); i.next(); var sb = new StringBuilder(); i.forEachRemaining(x -> sb.append(x)); return sb; });
        t("get(-1)", () -> fresh().subList(1, 3).get(-1));
        t("get(2)", () -> fresh().subList(1, 3).get(2));
        t("set(2)", () -> fresh().subList(1, 3).set(2, 1));
        t("set", () -> { var l = fresh(); var s = l.subList(1, 3); var old = s.set(0, 9); return old + " " + l + " " + s; });
        t("set then stale", () -> { var l = fresh(); var s = l.subList(1, 3); var u = l.subList(1, 3); s.set(0, 9); return u.get(0) + " " + s.get(0); });
        t("set then sibling", () -> { var l = fresh(); var s = l.subList(1, 3); var u = l.subList(2, 4); s.set(0, 9); return u.get(0); });
        t("add(3)", () -> { fresh().subList(1, 3).add(3, 1); return 1; });
        t("add(-1)", () -> { fresh().subList(1, 3).add(-1, 1); return 1; });
        t("add through", () -> { var l = fresh(); var s = l.subList(1, 3); s.add(9); s.add(0, 8); return l + " " + s; });
        t("add then sibling", () -> { var l = fresh(); var s = l.subList(1, 3); var u = l.subList(2, 4); s.add(9); return u.get(0); });
        t("remove(2)", () -> fresh().subList(1, 3).remove(2));
        t("remove(-1)", () -> fresh().subList(1, 3).remove(-1));
        t("remove through", () -> { var l = fresh(); var s = l.subList(1, 4); var x = s.remove(1); return x + " " + l + " " + s; });
        t("remove(o)", () -> { var l = fresh(); var s = l.subList(1, 4); return s.remove((Object) 2) + " " + s.remove((Object) 77) + " " + l + " " + s; });
        t("clear", () -> { var l = fresh(); var s = l.subList(1, 4); s.clear(); return l + " " + s; });
        t("clear empty", () -> { var l = fresh(); var s = l.subList(1, 1); s.clear(); return l + " " + s; });
        t("addAll", () -> { var l = fresh(); var s = l.subList(1, 3); return s.addAll(List.of(7, 8)) + " " + l + " " + s; });
        t("addAll(i)", () -> { var l = fresh(); var s = l.subList(1, 3); return s.addAll(1, List.of(7, 8)) + " " + l + " " + s; });
        t("addAll(i) empty", () -> { var l = fresh(); var s = l.subList(1, 3); return s.addAll(1, List.of()) + " " + l + " " + s; });
        t("addAll(i) bad", () -> fresh().subList(1, 3).addAll(3, List.of(1)));
        t("addAll(i) bad stale", () -> { var l = fresh(); var s = l.subList(1, 3); l.add(1); return s.addAll(9, List.of(1)); });
        t("addAll(i) empty stale", () -> { var l = fresh(); var s = l.subList(1, 3); l.add(1); return s.addAll(1, List.of()); });
        t("addAll empty stale", () -> { var l = fresh(); var s = l.subList(1, 3); l.add(1); return s.addAll(List.of()); });
        t("removeAll", () -> { var l = fresh(); var s = l.subList(1, 4); return s.removeAll(List.of(2, 9)) + " " + l + " " + s; });
        t("removeAll none", () -> { var l = fresh(); var s = l.subList(1, 4); return s.removeAll(List.of(9)) + " " + l + " " + s; });
        t("retainAll", () -> { var l = fresh(); var s = l.subList(1, 4); return s.retainAll(List.of(2, 9)) + " " + l + " " + s; });
        t("removeIf", () -> { var l = fresh(); var s = l.subList(1, 4); return s.removeIf(x -> x == 2) + " " + l + " " + s; });
        t("removeIf none", () -> { var l = fresh(); var s = l.subList(1, 4); var r = s.removeIf(x -> false); return r + " " + l + " " + s + " " + s.size(); });
        t("replaceAll", () -> { var l = fresh(); var s = l.subList(1, 4); s.replaceAll(x -> x * 10); return l + " " + s; });
        t("sort", () -> { var l = new CopyOnWriteArrayList<>(List.of(5, 4, 3, 2, 1)); var s = l.subList(1, 4); s.sort(null); return l + " " + s; });
        t("sort then use", () -> { var l = new CopyOnWriteArrayList<>(List.of(5, 4, 3, 2, 1)); var s = l.subList(1, 4); s.sort(null); return s.get(0); });
        t("replaceAll then use", () -> { var l = fresh(); var s = l.subList(1, 4); s.replaceAll(x -> x * 10); return s.get(0); });
        t("forEach", () -> { var s = fresh().subList(1, 4); var sb = new StringBuilder(); s.forEach(x -> sb.append(x)); return sb; });
        t("forEach stale", () -> { var l = fresh(); var s = l.subList(1, 4); l.add(1); s.forEach(x -> {}); return 1; });
        t("stream", () -> fresh().subList(1, 4).stream().mapToInt(x -> x).sum());
        t("stream stale", () -> { var l = fresh(); var s = l.subList(1, 4); l.add(1); return s.stream().count(); });
        t("spliterator", () -> { var s = fresh().subList(1, 4); var sp = s.spliterator(); return sp.estimateSize() + " " + sp.characteristics() + " " + sp.getExactSizeIfKnown(); });
        t("spliterator stale", () -> { var l = fresh(); var s = l.subList(1, 4); l.add(1); return s.spliterator(); });
        t("spliterator then add", () -> { var l = fresh(); var s = l.subList(1, 4); var sp = s.spliterator(); l.add(1); return sp.estimateSize(); });
        t("spliterator then add, tryAdvance", () -> { var l = fresh(); var s = l.subList(1, 4); var sp = s.spliterator(); l.add(1); return sp.tryAdvance(x -> {}); });
        t("spliterator then add, forEachRemaining", () -> { var l = fresh(); var s = l.subList(1, 4); var sp = s.spliterator(); l.add(1); sp.forEachRemaining(x -> {}); return 1; });
        t("spliterator trySplit", () -> { var s = fresh().subList(1, 5); var sp = s.spliterator(); var h = sp.trySplit(); return (h == null ? "null" : h.estimateSize()) + " " + sp.estimateSize(); });
        t("toString", () -> fresh().subList(1, 4).toString());
        t("toString stale", () -> { var l = fresh(); var s = l.subList(1, 4); l.add(1); return s.toString(); });
        t("equals", () -> fresh().subList(1, 3).equals(List.of(1, 2)));
        t("equals stale", () -> { var l = fresh(); var s = l.subList(1, 3); l.add(1); return s.equals(List.of(1, 2)); });
        t("equals other stale", () -> { var l = fresh(); var s = l.subList(1, 3); var u = l.subList(1, 3); l.add(1); return List.of(1, 2).equals(s) + " " + s.equals(u); });
        t("hashCode", () -> fresh().subList(1, 3).hashCode());
        t("hashCode stale", () -> { var l = fresh(); var s = l.subList(1, 3); l.add(1); return s.hashCode(); });
        t("indexOf", () -> fresh().subList(1, 4).indexOf(3) + " " + fresh().subList(1, 4).indexOf(0) + " " + fresh().subList(1, 4).lastIndexOf(1));
        t("indexOf stale", () -> { var l = fresh(); var s = l.subList(1, 4); l.add(1); return s.indexOf(3); });
        t("contains", () -> fresh().subList(1, 4).contains(3) + " " + fresh().subList(1, 4).contains(0));
        t("contains stale", () -> { var l = fresh(); var s = l.subList(1, 4); l.add(1); return s.contains(3); });
        t("containsAll", () -> fresh().subList(1, 4).containsAll(List.of(1, 3)));
        t("isEmpty", () -> fresh().subList(1, 1).isEmpty() + " " + fresh().subList(1, 2).isEmpty());
        t("isEmpty stale", () -> { var l = fresh(); var s = l.subList(1, 1); l.add(1); return s.isEmpty(); });
        t("toArray", () -> Arrays.toString(fresh().subList(1, 4).toArray()) + Arrays.toString(fresh().subList(1, 4).toArray(new Integer[0])));
        t("toArray stale", () -> { var l = fresh(); var s = l.subList(1, 4); l.add(1); return s.toArray().length; });
        t("subList", () -> { var l = fresh(); var s = l.subList(1, 5); var u = s.subList(1, 3); return u + " " + u.size(); });
        t("subList bad", () -> fresh().subList(1, 5).subList(0, 9));
        t("subList bad2", () -> fresh().subList(1, 5).subList(-1, 2));
        t("subList bad3", () -> fresh().subList(1, 5).subList(3, 2));
        t("subList stale", () -> { var l = fresh(); var s = l.subList(1, 5); l.add(1); return s.subList(0, 1); });
        t("subList stale bad", () -> { var l = fresh(); var s = l.subList(1, 5); l.add(1); return s.subList(0, 9); });
        t("subList of sub add", () -> { var l = fresh(); var s = l.subList(1, 5); var u = s.subList(1, 3); u.add(9); return l + " " + s + " " + u; });
        t("subList of sub, outer after inner add", () -> { var l = fresh(); var s = l.subList(1, 5); var u = s.subList(1, 3); u.add(9); return s.get(0) + " " + s.size(); });
        t("subList of sub, inner after outer add", () -> { var l = fresh(); var s = l.subList(1, 5); var u = s.subList(1, 3); s.add(9); return u.get(0); });
        t("subList of sub, inner after list add", () -> { var l = fresh(); var s = l.subList(1, 5); var u = s.subList(1, 3); l.add(9); return u.get(0); });
        t("subList of stale sub, new", () -> { var l = fresh(); var s = l.subList(1, 5); l.add(1); try { s.subList(0, 1); } catch (Exception e) { return "caught"; } return "made"; });
        t("sub of list sub", () -> { var l = fresh(); var s = l.subList(1, 5); var u = l.subList(0, 2); return u + " " + s; });
        t("subList(0,0) of empty", () -> new CopyOnWriteArrayList<Integer>().subList(0, 0));
        t("subList bad list", () -> fresh().subList(0, 9));
        t("subList bad list2", () -> fresh().subList(-1, 2));
        t("subList bad list3", () -> fresh().subList(3, 2));
        t("class", () -> fresh().subList(1, 3).getClass().getName());
        t("class of sub", () -> fresh().subList(1, 3).subList(0, 1).getClass().getName());
        t("RandomAccess", () -> fresh().subList(1, 3) instanceof RandomAccess);
        t("reversed", () -> fresh().subList(1, 4).reversed());
        t("reversed stale", () -> { var l = fresh(); var s = l.subList(1, 4); l.add(1); return s.reversed(); });
        t("getFirst", () -> fresh().subList(1, 4).getFirst() + " " + fresh().subList(1, 4).getLast());
        t("getFirst empty", () -> fresh().subList(1, 1).getFirst());
        t("removeFirst", () -> { var l = fresh(); var s = l.subList(1, 4); return s.removeFirst() + " " + l + " " + s; });
        t("addFirst", () -> { var l = fresh(); var s = l.subList(1, 4); s.addFirst(9); return l + " " + s; });
        t("addLast", () -> { var l = fresh(); var s = l.subList(1, 4); s.addLast(9); return l + " " + s; });
        t("a sub of sub class", () -> { var l = fresh(); return l.subList(0, 3).getClass() == l.subList(0, 3).subList(0, 1).getClass(); });
        t("iter exhaust then add", () -> { var l = fresh(); var s = l.subList(1, 3); var i = s.iterator(); i.next(); i.next(); s.add(9); return i.hasNext(); });
        t("listIterator hasPrevious after l add", () -> { var l = fresh(); var s = l.subList(1, 3); var i = s.listIterator(); l.add(9); return i.hasPrevious() + " " + i.nextIndex() + " " + i.previousIndex(); });
        t("synchronized view", () -> { var l = fresh(); var s = l.subList(1, 3); synchronized (s) { return s.size(); } });
        t("sub of cow of sub equal", () -> { var l = fresh(); return l.subList(1, 3).equals(new ArrayList<>(List.of(1, 2))) + " " + new ArrayList<>(List.of(1, 2)).equals(l.subList(1, 3)); });
        t("Collections.sort on part", () -> { var l = new CopyOnWriteArrayList<>(List.of(5, 4, 3, 2, 1)); var s = l.subList(1, 4); Collections.sort(s); return l + " " + s; });
        t("Collections.reverse on part", () -> { var l = fresh(); var s = l.subList(1, 4); Collections.reverse(s); return l + " " + s; });
        t("Collections.shuffle on part", () -> { var l = fresh(); var s = l.subList(1, 4); Collections.shuffle(s, new Random(1)); return l + " " + s; });
        t("new ArrayList(part)", () -> { var l = fresh(); var s = l.subList(1, 4); return new ArrayList<>(s); });
        t("new ArrayList(part stale)", () -> { var l = fresh(); var s = l.subList(1, 4); l.add(1); return new ArrayList<>(s); });
        t("list.addAll(part)", () -> { var l = fresh(); var s = l.subList(1, 3); return l.addAll(s) + " " + l; });
        t("list.addAll(part stale)", () -> { var l = fresh(); var s = l.subList(1, 3); l.add(1); return l.addAll(s) + " " + l; });
        t("list.containsAll(part)", () -> { var l = fresh(); var s = l.subList(1, 3); return l.containsAll(s); });
    }
}
